# Fingerly first-party proxy for nginx, version 1.0.0.
#
# Load the njs module in the main context of nginx.conf, define the native SDK
# platform allowlist in `http`, and include this file inside the `server`
# block that serves your site, so SDKs post to your own host. fingerly.js,
# the response header allowlist, sits beside nginx.conf. The map keeps the
# platform only for a request without Origin, so one channel header goes
# upstream:
#
#     load_module modules/ngx_http_js_module.so;
#
#     map "$http_origin:$http_x_fingerly_sdk_platform" $fingerly_platform {
#         default "";
#         "~^:(ios|android|react-native|react-native-ios|react-native-android|flutter|flutter-ios|flutter-android|lynx-ios|lynx-android|capacitor|kotlin-multiplatform)$" $1;
#     }
#
#     server {
#         server_name www.example.com;
#         include /etc/nginx/snippets/fingerly.conf;
#         ...
#     }
#
# `/k7x2qm4a` is the path the Fingerly dashboard issued for this proxy. The
# location answers exactly that path, nothing under or beside it.

location = /k7x2qm4a {
    # The proxy key lives in its own file, readable only by root and kept out of
    # version control. It holds one line:
    #     set $fingerly_proxy_key "fly_px_...";
    include /etc/nginx/fingerly-proxy-key.conf;
    default_type application/json;
    # nginx names itself without its version.
    server_tokens off;
    # Response headers are an allowlist, kept by fingerly.js (needs the njs
    # module): only the relayed headers reach the page, whatever the API sends.
    # A redirect, or any status outside 200 to 599, is answered 502 there, with
    # none of its headers or body.
    js_import fingerly from /etc/nginx/fingerly.js;
    js_var $fingerly_refused;
    js_header_filter fingerly.relay;
    js_body_filter fingerly.body;

    # nginx matched the location on the cleaned path, after resolving dot
    # segments, merging slashes and decoding characters. The raw request
    # target must be exactly the path too, optionally with a query string.
    if ($request_uri !~ "^/k7x2qm4a(\?|$)") {
        add_header Cache-Control "no-store" always;
        return 404;
    }
    if ($request_method != POST) {
        add_header Allow "POST" always;
        add_header Cache-Control "no-store" always;
        return 405;
    }
    # A key that is not shaped like a proxy key answers 503 rather than
    # forwarding anything.
    if ($fingerly_proxy_key !~ "^fly_px_(production|staging|development)_[A-Za-z0-9_-]+$") {
        add_header Cache-Control "no-store" always;
        return 503;
    }

    # Reject with 400 missing_origin when both Origin and validated
    # X-Fingerly-SDK-Platform ($fingerly_platform) are empty. Never synthesize
    # X-Fingerly-Origin from Host.
    set $fingerly_gate "${http_origin}${fingerly_platform}";
    if ($fingerly_gate = "") {
        add_header Cache-Control "no-store" always;
        return 400 '{"error":{"code":"missing_origin","message":"Origin or X-Fingerly-SDK-Platform header is required"}}';
    }

    # X-Api-Key must be a public key of the proxy key's environment. Anything
    # else, a missing header or a secret fly_sk_ key included, answers 401 and
    # nothing is forwarded.
    set $fingerly_keys "${fingerly_proxy_key} ${http_x_api_key}";
    if ($fingerly_keys !~ "^fly_px_(production|staging|development)_[A-Za-z0-9_-]+ fly_pk_\1_[A-Za-z0-9_-]+$") {
        add_header Cache-Control "no-store" always;
        return 401;
    }

    client_max_body_size 1m;

    # The one URL this location can reach. Single-pass browser and native SDK
    # submissions go here as raw bytes.
    proxy_pass https://api.fingerly.io/api/v1/ingest;
    proxy_http_version 1.1;
    proxy_ssl_server_name on;
    proxy_ssl_verify on;
    proxy_ssl_verify_depth 3;
    proxy_ssl_trusted_certificate /etc/ssl/certs/ca-certificates.crt;
    proxy_redirect off;
    proxy_connect_timeout 5s;
    proxy_send_timeout 5s;
    proxy_read_timeout 5s;

    # Request headers are an allowlist: nothing the visitor sent reaches the API
    # unless it is named here. Cookies, Authorization and any visitor-sent
    # X-Fingerly-* header are dropped by construction. An empty value is not
    # sent at all.
    proxy_pass_request_headers off;
    proxy_set_header Host api.fingerly.io;
    proxy_set_header Content-Type $content_type;
    proxy_set_header X-Api-Key $http_x_api_key;
    proxy_set_header Idempotency-Key $http_idempotency_key;
    proxy_set_header User-Agent $http_user_agent;
    proxy_set_header Sec-Fetch-Site $http_sec_fetch_site;
    proxy_set_header Sec-Fetch-Mode $http_sec_fetch_mode;
    proxy_set_header Sec-Fetch-Dest $http_sec_fetch_dest;
    proxy_set_header Sec-CH-UA $http_sec_ch_ua;
    proxy_set_header Sec-CH-UA-Mobile $http_sec_ch_ua_mobile;
    proxy_set_header Sec-CH-UA-Platform $http_sec_ch_ua_platform;
    # Web Bot Auth: the signature an AI agent's browser adds to the request.
    proxy_set_header Signature $http_signature;
    proxy_set_header Signature-Input $http_signature_input;
    proxy_set_header Signature-Agent $http_signature_agent;
    proxy_set_header X-Fingerly-Proxy-Key $fingerly_proxy_key;
    # The address of the connection nginx accepted. Behind a load balancer, set
    # up the realip module so this is the visitor, not the load balancer.
    proxy_set_header X-Fingerly-Client-Ip $remote_addr;
    proxy_set_header X-Fingerly-Origin $http_origin;
    proxy_set_header X-Fingerly-Host $http_host;
    # One channel only: $fingerly_platform is empty whenever Origin is sent.
    proxy_set_header X-Fingerly-SDK-Platform $fingerly_platform;
    proxy_set_header X-Fingerly-User-Agent $http_user_agent;
    proxy_set_header X-Fingerly-Proxy-Version "nginx/1.0.0";

    # The API's own Cache-Control is replaced by no-store; fingerly.js drops
    # every other header outside the relay list.
    proxy_hide_header Cache-Control;
    add_header Cache-Control "no-store" always;
}

// Fingerly first-party proxy for nginx, version 1.0.0: the response header
// allowlist, run by the njs module as a header filter of the proxy location.
//
// Core nginx can only hide named upstream headers. A blocker can match a
// response header by name, so an allowlist is what guarantees nothing on the
// way back names Fingerly, whatever the API sends in future. nginx adds its
// own Date, Server and framing headers after this filter runs.

/** The response headers relayed to the caller, plus the pinned Cache-Control and framing. */
var RELAYED = [
  'content-type',
  'x-request-id',
  'ratelimit-limit',
  'ratelimit-remaining',
  'retry-after',
  'cache-control',
  'allow',
  'content-length',
  'content-encoding',
  'transfer-encoding',
]

/** Only a final answer in 200 to 599, outside 300 to 399, is relayed. */
function relayable(status) {
  return status >= 200 && status <= 599 && (status < 300 || status > 399)
}

// Plain ES5 loops: the default njs engine supports no `for...of`.
function relay(r) {
  // A redirect, or any status outside 200 to 599, is answered 502 with none
  // of its headers; `body` below replaces what it carried.
  var refused = !relayable(r.status)
  if (refused) {
    r.variables.fingerly_refused = '1'
    r.status = 502
  }
  var names = Object.keys(r.headersOut)
  for (var i = 0; i < names.length; i++) {
    var name = names[i].toLowerCase()
    if (refused ? name !== 'cache-control' : RELAYED.indexOf(name) === -1) delete r.headersOut[names[i]]
  }
  if (refused) r.headersOut['Content-Type'] = 'text/plain; charset=utf-8'
}

function body(r, data, flags) {
  if (r.variables.fingerly_refused !== '1') return r.sendBuffer(data, flags)
  if (flags.last) r.sendBuffer('Bad gateway', flags)
}

export default { relay, body }

# Main context, beside the other load_module lines.
load_module modules/ngx_http_js_module.so;

# In http:
map "$http_origin:$http_x_fingerly_sdk_platform" $fingerly_platform {
    default "";
    "~^:(ios|android|react-native|react-native-ios|react-native-android|flutter|flutter-ios|flutter-android|lynx-ios|lynx-android|capacitor|kotlin-multiplatform)$" $1;
}

server {
    server_name www.example.com;
    include /etc/nginx/snippets/fingerly.conf;
    # ...
}

await load({
  apiKey: 'fly_pk_production_…',
  endpoints: '/k7x2qm4a',
  consent: 'granted', // only once the visitor has agreed, or you know none is needed (docs/privacy.md §4)
})

# Exactly the issued path, compared on the raw request target, then
# nothing or a query string. A plain path matcher would ignore case and
# match after resolving dot segments, merging slashes and decoding
# characters.
@fingerly vars_regexp {http.request.orig_uri} ^/k7x2qm4a(?:[?].*)?$
handle @fingerly {
	route {
		# Deferred, so it replaces whatever the API sends and also covers the
		# responses Caddy writes itself.
		header >Cache-Control no-store
		# Caddy names itself in a Via header of its own; deletions are deferred too.
		header -Via

		@notpost not method POST
		header @notpost Allow POST
		respond @notpost 405

		# A key that is not shaped like a proxy key answers 503 rather than
		# forwarding anything.
		@nokey not vars_regexp {env.FINGERLY_PROXY_KEY} ^fly_px_(production|staging|development)_[A-Za-z0-9_-]+$
		respond @nokey 503

		# 1. Capture validated lowercase X-Fingerly-SDK-Platform; anything else becomes "".
		vars fingerly_platform ""
		@validplatform vars_regexp {http.request.header.X-Fingerly-SDK-Platform} ^(ios|android|react-native|react-native-ios|react-native-android|flutter|flutter-ios|flutter-android|lynx-ios|lynx-android|capacitor|kotlin-multiplatform)$
		vars @validplatform fingerly_platform {http.request.header.X-Fingerly-SDK-Platform}

		# 2-4. Reject with 400 missing_origin iff both Origin and validated platform are empty.
		@missingorigin {
			not header_regexp Origin .
			vars {http.vars.fingerly_platform} ""
		}
		header @missingorigin Content-Type application/json
		respond @missingorigin `{"error":{"code":"missing_origin","message":"Origin or X-Fingerly-SDK-Platform header is required"}}` 400

		# X-Api-Key must be a public key of the proxy key's environment.
		# Anything else, a missing header or a secret fly_sk_ key included,
		# answers 401 and nothing is forwarded.
		vars fingerly_public_key ""
		@proxyenv vars_regexp proxyenv {env.FINGERLY_PROXY_KEY} ^fly_px_(production|staging|development)_
		vars @proxyenv fingerly_key_pair "{re.proxyenv.1} {http.request.header.X-Api-Key}"
		@public vars_regexp {http.vars.fingerly_key_pair} "^(production fly_pk_production|staging fly_pk_staging|development fly_pk_development)_[A-Za-z0-9_-]+$"
		vars @public fingerly_public_key {http.request.header.X-Api-Key}
		@notpublic vars {http.vars.fingerly_public_key} ""
		respond @notpublic 401

		request_body {
			max_size 1MiB
		}

		# 2-3. Request headers are an allowlist. The contract's client headers
		# are kept aside, every incoming header is removed (cookies,
		# Authorization, Referer, forwarding headers, application headers and
		# any visitor-sent X-Fingerly-* header among them), and only the kept
		# ones the visitor sent are set again. A header that was not sent is
		# not sent at all.
		vars {
			fingerly_content_type application/json
			fingerly_idempotency_key {http.request.header.Idempotency-Key}
			fingerly_user_agent {http.request.header.User-Agent}
			fingerly_sec_fetch_site {http.request.header.Sec-Fetch-Site}
			fingerly_sec_fetch_mode {http.request.header.Sec-Fetch-Mode}
			fingerly_sec_fetch_dest {http.request.header.Sec-Fetch-Dest}
			fingerly_sec_ch_ua {http.request.header.Sec-CH-UA}
			fingerly_sec_ch_ua_mobile {http.request.header.Sec-CH-UA-Mobile}
			fingerly_sec_ch_ua_platform {http.request.header.Sec-CH-UA-Platform}
			fingerly_signature {http.request.header.Signature}
			fingerly_signature_input {http.request.header.Signature-Input}
			fingerly_signature_agent {http.request.header.Signature-Agent}
			fingerly_origin {http.request.header.Origin}
			# Kept aside too: removing every header below clears the request's
			# host as well.
			fingerly_host {http.request.hostport}
		}
		@sentcontenttype header_regexp Content-Type .
		vars @sentcontenttype fingerly_content_type {http.request.header.Content-Type}

		request_header -*
		request_header Content-Type {http.vars.fingerly_content_type}
		request_header X-Api-Key {http.vars.fingerly_public_key}
		@sentidempotencykey not vars {http.vars.fingerly_idempotency_key} ""
		request_header @sentidempotencykey Idempotency-Key {http.vars.fingerly_idempotency_key}
		@sentuseragent not vars {http.vars.fingerly_user_agent} ""
		request_header @sentuseragent User-Agent {http.vars.fingerly_user_agent}
		request_header @sentuseragent X-Fingerly-User-Agent {http.vars.fingerly_user_agent}
		@sentsecfetchsite not vars {http.vars.fingerly_sec_fetch_site} ""
		request_header @sentsecfetchsite Sec-Fetch-Site {http.vars.fingerly_sec_fetch_site}
		@sentsecfetchmode not vars {http.vars.fingerly_sec_fetch_mode} ""
		request_header @sentsecfetchmode Sec-Fetch-Mode {http.vars.fingerly_sec_fetch_mode}
		@sentsecfetchdest not vars {http.vars.fingerly_sec_fetch_dest} ""
		request_header @sentsecfetchdest Sec-Fetch-Dest {http.vars.fingerly_sec_fetch_dest}
		@sentsecchua not vars {http.vars.fingerly_sec_ch_ua} ""
		request_header @sentsecchua Sec-CH-UA {http.vars.fingerly_sec_ch_ua}
		@sentsecchuamobile not vars {http.vars.fingerly_sec_ch_ua_mobile} ""
		request_header @sentsecchuamobile Sec-CH-UA-Mobile {http.vars.fingerly_sec_ch_ua_mobile}
		@sentsecchuaplatform not vars {http.vars.fingerly_sec_ch_ua_platform} ""
		request_header @sentsecchuaplatform Sec-CH-UA-Platform {http.vars.fingerly_sec_ch_ua_platform}
		# Web Bot Auth: the signature an AI agent's browser adds to the request.
		@sentsignature not vars {http.vars.fingerly_signature} ""
		request_header @sentsignature Signature {http.vars.fingerly_signature}
		@sentsignatureinput not vars {http.vars.fingerly_signature_input} ""
		request_header @sentsignatureinput Signature-Input {http.vars.fingerly_signature_input}
		@sentsignatureagent not vars {http.vars.fingerly_signature_agent} ""
		request_header @sentsignatureagent Signature-Agent {http.vars.fingerly_signature_agent}
		# X-Fingerly-Origin only when Origin was sent; never synthesized from Host.
		@sentorigin not vars {http.vars.fingerly_origin} ""
		request_header @sentorigin X-Fingerly-Origin {http.vars.fingerly_origin}
		# The validated platform, restored only when it matched and Origin
		# was not sent: one channel header goes upstream, never both.
		@hasplatform {
			not vars {http.vars.fingerly_platform} ""
			vars {http.vars.fingerly_origin} ""
		}
		request_header @hasplatform X-Fingerly-SDK-Platform {http.vars.fingerly_platform}
		# The host the visitor sent the request to, which the API checks a
		# Web Bot Auth signature against.
		@senthost not vars {http.vars.fingerly_host} ""
		request_header @senthost X-Fingerly-Host {http.vars.fingerly_host}

		# The one URL this block can reach. Single-pass browser and native SDK
		# submissions go here as raw bytes.
		rewrite * /api/v1/ingest
		reverse_proxy https://api.fingerly.io {
			header_up Host {upstream_hostport}
			# Caddy's own forwarding headers: the API reads the visitor's address
			# only from X-Fingerly-Client-Ip.
			header_up -X-Forwarded-For
			header_up -X-Forwarded-Proto
			header_up -X-Forwarded-Host
			header_up -Via
			header_up X-Fingerly-Proxy-Key {env.FINGERLY_PROXY_KEY}
			# The visitor's address. Behind a load balancer, set trusted_proxies
			# (and trusted_proxies_strict) so this is the visitor, not the load
			# balancer. See the README.
			header_up X-Fingerly-Client-Ip {client_ip}
			header_up X-Fingerly-Proxy-Version caddy/1.0.0

			transport http {
				dial_timeout 5s
				response_header_timeout 5s
			}

			# Response headers are an allowlist too. Nothing the API sends is
			# copied as it is; only the relayed headers it sent are set again.
			# Cache-Control is pinned above. The placeholders spell each name the
			# way Go stores it (Ratelimit-Limit, not RateLimit-Limit).
			header_down -*
			# A redirect is never followed or relayed, and neither is a status
			# outside 200 to 599: each is answered 502, with none of its headers
			# or body.
			@unrelayable status 1xx 3xx 6xx 7xx 8xx 9xx
			handle_response @unrelayable {
				respond "Bad gateway" 502
			}
			handle_response {
				@relaycontenttype not vars {rp.header.Content-Type} ""
				header @relaycontenttype Content-Type {rp.header.Content-Type}
				@relayrequestid not vars {rp.header.X-Request-Id} ""
				header @relayrequestid X-Request-Id {rp.header.X-Request-Id}
				@relayratelimitlimit not vars {rp.header.Ratelimit-Limit} ""
				header @relayratelimitlimit RateLimit-Limit {rp.header.Ratelimit-Limit}
				@relayratelimitremaining not vars {rp.header.Ratelimit-Remaining} ""
				header @relayratelimitremaining RateLimit-Remaining {rp.header.Ratelimit-Remaining}
				@relayretryafter not vars {rp.header.Retry-After} ""
				header @relayretryafter Retry-After {rp.header.Retry-After}
				copy_response
			}
		}
	}
}

await load({
  apiKey: 'fly_pk_production_…',
  endpoints: '/k7x2qm4a',
  consent: 'granted', // only once the visitor has agreed, or you know none is needed (docs/privacy.md §4)
})

/**
 * Fingerly first-party proxy as Vercel Routing Middleware, version 1.0.0.
 *
 * Put this file at the root of your project, beside package.json. It answers
 * the one path the Fingerly dashboard issued (`/k7x2qm4a` below; the matcher and
 * PATH must both hold it) and forwards single-pass browser and native SDK
 * submissions as raw bytes to the Fingerly API. The proxy key comes from the
 * FINGERLY_PROXY_KEY environment variable. No dependencies: web-standard
 * Request and Response only.
 */
export const config = { matcher: '/k7x2qm4a' }

/** The path the dashboard issued. Keep it equal to the matcher above. */
const PATH = '/k7x2qm4a'
const VERSION = '1.0.0'
const MAX_BODY_BYTES = 1_048_576
const UPSTREAM_TIMEOUT_MS = 5_000
/**
 * The one URL this middleware can reach. A constant rather than anything
 * derived from configuration: a misconfigured deployment must not be able to
 * send your traffic somewhere else. Single-pass browser and native SDK
 * submissions go here as raw bytes.
 */
const UPSTREAM = 'https://api.fingerly.io/api/v1/ingest'

/** Exact lowercase platform names accepted on the native SDK channel. */
const SDK_PLATFORM_RE = /^(ios|android|react-native|react-native-ios|react-native-android|flutter|flutter-ios|flutter-android|lynx-ios|lynx-android|capacitor|kotlin-multiplatform)$/

/** Allowlisted client headers forwarded verbatim when present. */
const FORWARDED_CLIENT_HEADERS = [
  'idempotency-key',
  'user-agent',
  'sec-fetch-site',
  'sec-fetch-mode',
  'sec-fetch-dest',
  'sec-ch-ua',
  'sec-ch-ua-mobile',
  'sec-ch-ua-platform',
]

/**
 * Web Bot Auth headers an AI agent's browser signs the request with, forwarded
 * when present and at most 4096 bytes. The API ignores a longer one, so it is
 * dropped here rather than refused.
 */
const SIGNATURE_HEADERS = ['signature', 'signature-input', 'signature-agent']
const MAX_SIGNATURE_HEADER_BYTES = 4096

/**
 * The response headers relayed to the caller, and nothing else. A blocker can
 * match a response header by name, so an allowlist is what guarantees nothing
 * on the way back names Fingerly, whatever the API sends in future.
 */
const RELAYED_HEADERS = ['content-type', 'x-request-id', 'ratelimit-limit', 'ratelimit-remaining', 'retry-after']

/** Whether the configured value is shaped like a Fingerly proxy key. */
function isProxyKey(key: string): boolean {
  return /^fly_px_(?:production|staging|development)_[A-Za-z0-9_-]+$/.test(key)
}

/**
 * Whether the caller's X-Api-Key is a public key of the proxy key's
 * environment. Anything else, a secret `fly_sk_` key included, is answered 401
 * here rather than sent upstream.
 */
function isPublicKeyFor(proxyKey: string, publicKey: string | null): publicKey is string {
  const environment = /^fly_px_(production|staging|development)_/.exec(proxyKey)?.[1]
  return Boolean(environment) && new RegExp(`^fly_pk_${environment}_[A-Za-z0-9_-]+$`).test(publicKey ?? '')
}

/** Whether the request is for the one configured path. */
function isProxyPath(pathname: string): boolean {
  // Exactly: no trailing slash, nothing under it, case-sensitive.
  return pathname === PATH
}

/**
 * The visitor's address: x-real-ip, which Vercel sets on every request to the
 * address its edge accepted the connection from, replacing whatever the
 * visitor sent. Nothing else is read. x-forwarded-for in particular is not a
 * fallback: anywhere its entries are passed along rather than rewritten, the
 * left-most one is whatever the visitor chose to write. Without a valid
 * x-real-ip nothing is forwarded.
 */
function clientIp(request: Request): string {
  return (request.headers.get('x-real-ip') ?? '').trim()
}

/** Only a final answer in 200 to 599, outside 300 to 399, is relayed. */
function relayable(status: number): boolean {
  return status >= 200 && status <= 599 && (status < 300 || status > 399)
}

function plain(status: number, message: string, extra: Record<string, string> = {}): Response {
  return new Response(message, { status, headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'no-store', ...extra } })
}

function jsonError(status: number, code: string, message: string): Response {
  return new Response(JSON.stringify({ error: { code, message } }), {
    status,
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store' },
  })
}

const IPV4 = /^(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(?:\.(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/

/** Whether the value is one IPv4 or IPv6 literal and nothing else. */
function isIpLiteral(value: string): boolean {
  if (IPV4.test(value)) return true
  if (!/^[0-9A-Fa-f:.]+$/.test(value) || !value.includes(':')) return false
  try {
    return new URL(`http://[${value}]/`).hostname.length > 2
  } catch {
    return false
  }
}

/** Reported once per instance rather than per request: it is configuration. */
let reportedMissingAddress = false

function noAddress(): Response {
  if (!reportedMissingAddress) {
    reportedMissingAddress = true
    console.error('proxy: the client IP callback returned no valid address; nothing was forwarded')
  }
  return plain(500, 'The client IP callback returned no valid address')
}

/** The most of an answer relayed: an answer is a few kilobytes. */
const MAX_RESPONSE_BYTES = 4 * 1_048_576

/** Reads a body to its end, or returns null once it passes `limit` bytes. */
async function readCapped(body: ReadableStream<Uint8Array> | null, limit: number): Promise<Uint8Array | null> {
  if (!body) return new Uint8Array(0)
  const reader = body.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    size += value.byteLength
    if (size > limit) {
      await reader.cancel().catch(() => undefined)
      return null
    }
    chunks.push(value)
  }
  const out = new Uint8Array(size)
  let offset = 0
  for (const chunk of chunks) {
    out.set(chunk, offset)
    offset += chunk.byteLength
  }
  return out
}

export default async function middleware(request: Request): Promise<Response> {
  const url = new URL(request.url)
  if (!isProxyPath(url.pathname)) return plain(404, 'Not Found')
  if (request.method !== 'POST') return plain(405, 'Method Not Allowed', { allow: 'POST' })

  const proxyKey = process.env.FINGERLY_PROXY_KEY ?? ''
  if (!isProxyKey(proxyKey)) return plain(503, 'Service Unavailable')

  // 1. Capture validated lowercase x-fingerly-sdk-platform; anything else is discarded.
